package com.example.onlineshop.catalog.persistence;
import com.example.onlineshop.catalog.application.*;import com.example.onlineshop.catalog.domain.*;import java.sql.*;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;import org.springframework.transaction.annotation.Transactional;
@Repository public class PostgresProductRepository implements CatalogProductRepository {
 private static final String PROJECTION="SELECT p.id,p.name,p.description,s.price_amount,s.currency,s.available_quantity,p.created_at,p.updated_at FROM product p JOIN product_sku s ON s.product_id=p.id AND s.is_default";
 private final JdbcTemplate jdbc;public PostgresProductRepository(JdbcTemplate jdbc){this.jdbc=jdbc;}
 @Override @Transactional public CatalogProduct save(CatalogProduct p){p.defaultSku();Timestamp created=Timestamp.from(p.createdAt()),updated=Timestamp.from(p.updatedAt());jdbc.update("INSERT INTO product (id,legacy_id,slug,name,description,status,created_at,created_by,updated_at,updated_by,version) VALUES (?,?,?,?,?,?,?,?,?,?,?)",p.id(),p.legacyId(),p.slug(),p.name(),p.description(),p.status().name(),created,p.createdBy(),updated,p.updatedBy(),p.version());for(ProductSku sku:p.skus())jdbc.update("INSERT INTO product_sku (id,product_id,sku,status,price_amount,currency,available_quantity,is_default,variant_signature,created_at,created_by,updated_at,updated_by,version) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)",sku.id(),p.id(),sku.sku(),sku.status().name(),sku.price(),sku.currency(),sku.availableQuantity(),sku.defaultSku(),sku.variantSignature(),created,p.createdBy(),updated,p.updatedBy(),sku.version());return p;}
 @Override @Transactional public ProductAttribute save(ProductAttribute a,UUID actor,java.time.Instant now){Timestamp timestamp=Timestamp.from(now);jdbc.update("INSERT INTO product_attribute (id,code,name,data_type,scope,is_variant_axis,status,created_at,created_by,updated_at,updated_by) VALUES (?,?,?,?,?,?,?, ?,?,?,?)",a.id(),a.code(),a.name(),a.dataType().name(),a.scope().name(),a.variantAxis(),a.status().name(),timestamp,actor,timestamp,actor);for(AttributeValue v:a.values()){Object text=null,integer=null,decimal=null,bool=null;switch(v.dataType()){case TEXT->text=v.value();case INTEGER->integer=v.value();case DECIMAL->decimal=v.value();case BOOLEAN->bool=v.value();}jdbc.update("INSERT INTO product_attribute_value (id,attribute_id,attribute_data_type,text_value,integer_value,decimal_value,boolean_value,display_value,created_at,created_by,updated_at,updated_by) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)",v.id(),v.attributeId(),v.dataType().name(),text,integer,decimal,bool,v.displayValue(),timestamp,actor,timestamp,actor);}return a;}
 @Override public Category save(Category c,UUID actor,java.time.Instant now){Timestamp timestamp=Timestamp.from(now);jdbc.update("INSERT INTO category (id,slug,name,parent_id,status,display_order,created_at,created_by,updated_at,updated_by,version) VALUES (?,?,?,?,?,?,?,?,?,?,?)",c.id(),c.slug(),c.name(),c.parentId(),c.status().name(),c.displayOrder(),timestamp,actor,timestamp,actor,c.version());return c;}
 @Override public ProductImage save(ProductImage i,UUID actor,java.time.Instant now){Timestamp timestamp=Timestamp.from(now);jdbc.update("INSERT INTO product_image (id,product_id,product_sku_id,url,alt_text,display_order,is_primary,created_at,created_by,updated_at,updated_by,version) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)",i.id(),i.productId(),i.skuId(),i.url(),i.altText(),i.displayOrder(),i.primary(),timestamp,actor,timestamp,actor,i.version());return i;}
 @Override public Optional<Product> findV1(UUID id){return jdbc.query(PROJECTION+" WHERE p.id=?",this::map,id).stream().findFirst();}
 @Override public ProductRepository.Page findV1Page(int page,int size){long total=jdbc.queryForObject("SELECT count(*) FROM product",Long.class);var content=jdbc.query(PROJECTION+" ORDER BY p.created_at DESC,p.id DESC LIMIT ? OFFSET ?",this::map,size,(long)page*size);return new ProductRepository.Page(content,total);}
 private Product map(ResultSet r,int row)throws SQLException{return new Product(r.getObject("id",UUID.class),r.getString("name"),r.getString("description"),r.getBigDecimal("price_amount"),r.getString("currency").trim(),r.getInt("available_quantity"),r.getTimestamp("created_at").toInstant(),r.getTimestamp("updated_at").toInstant());}
}
